===== EnsureUniqueIdentity.java =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.model.Owner;
     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
     8	
     9	/**
    10	 * The single duplicate-detection step in the create-owner pipeline, consolidating what used to be
    11	 * separate telephone, email and household checks. Runs after the telephone and email are normalized
    12	 * and after {@link DeriveHouseholdId} has resolved any shared {@code householdId}.
    13	 *
    14	 * <p>It applies two 409 rules against the already-stored owners:
    15	 * <ul>
    16	 * <li><b>Identity duplicate</b> — the request's {@code identityKey}, derived exactly as
    17	 * {@link Owner#getIdentityKey()} does ({@code normalizedTelephone|email|householdId}, email and
    18	 * householdId empty when absent), equals an existing owner's whole key. This always rejects, even
    19	 * with {@code sharesHousehold}.</li>
    20	 * <li><b>Household duplicate</b> — the request's computed {@code householdId} (from lastName and
    21	 * postcode) matches an existing owner's. Because the household is keyed on {@code (lastName,
    22	 * postcode)}, a second owner in that household is a duplicate <em>unless</em> it declares
    23	 * {@code sharesHousehold}, which admits it as a member.</li>
    24	 * </ul>
    25	 */
    26	public class EnsureUniqueIdentity {
    27	
    28	    public void service(@Val OwnerFieldsDto request, @Val HouseholdId householdId,
    29	            OwnerRepository ownerRepository) throws DuplicateIdentityException {
    30	        String householdIdValue = (householdId == null) ? null : householdId.value();
    31	        String identityKey = identityKey(request, householdIdValue);
    32	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
    33	        for (Owner existing : ownerRepository.findAll()) {
    34	            if (Boolean.TRUE.equals(existing.getDeleted())) {
    35	                continue; // soft-deleted owners no longer block a create
    36	            }
    37	            if (identityKey.equals(existing.getIdentityKey())) {
    38	                throw new DuplicateIdentityException(identityKey);
    39	            }
    40	            // A household of one (no postcode) shares with no one; sharesHousehold admits a member.
    41	            if (!sharesHousehold && householdIdValue != null
    42	                    && householdIdValue.equals(existing.getHouseholdId())) {
    43	                throw new DuplicateIdentityException(householdIdValue);
    44	            }
    45	        }
    46	    }
    47	
    48	    /** Derive the key for the owner being created, matching {@link Owner#getIdentityKey()} exactly. */
    49	    private static String identityKey(OwnerFieldsDto request, String householdId) {
    50	        String tel = request.getTelephone() == null ? "" : request.getTelephone();
    51	        String email = request.getEmail();
    52	        String mail = (email == null || email.isBlank()) ? "" : email;
    53	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
    54	        return tel + "|" + mail + "|" + household;
    55	    }
    56	}
===== DetectPossibleDuplicate.java =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.model.Owner;
     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	
     7	/**
     8	 * Soft-match step in the create-owner pipeline. Runs after {@link BuildOwner} (so the owner carries
     9	 * its normalized telephone, lastName and postcode) and before {@link SaveOwner}. It is reached only
    10	 * for owners that already passed {@link EnsureUniqueIdentity}, i.e. that are NOT hard duplicates.
    11	 *
    12	 * <p>An owner is a <em>possible</em> duplicate when an existing owner shares its {@code lastName}
    13	 * and {@code postcode} but has a different {@code telephone}. When such an owner exists the new
    14	 * owner is still created, but flagged with {@code possibleDuplicate = true} and
    15	 * {@code possibleDuplicateOf} set to the matching owner's id (the lowest id when several match).
    16	 * Otherwise {@code possibleDuplicate} is set to {@code false} and no match id is recorded.
    17	 *
    18	 * <p>An existing owner in the <em>same household</em> (same computed {@code householdId}) is never a
    19	 * soft match: a second owner sharing lastName and postcode is either rejected as a household
    20	 * duplicate ({@link EnsureUniqueIdentity}) or admitted as a declared member via
    21	 * {@code sharesHousehold}, and a declared member is not a suspected duplicate.
    22	 */
    23	public class DetectPossibleDuplicate {
    24	
    25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
    26	        owner.setPossibleDuplicate(false);
    27	        owner.setPossibleDuplicateOf(null);
    28	
    29	        String lastName = owner.getLastName();
    30	        String postcode = owner.getPostcode();
    31	        String telephone = owner.getTelephone();
    32	        if (lastName == null || postcode == null || postcode.isBlank()) {
    33	            return; // a shared lastName+postcode is required to be a possible duplicate
    34	        }
    35	
    36	        Integer matchId = null;
    37	        for (Owner existing : ownerRepository.findAll()) {
    38	            if (existing.getId() == null) {
    39	                continue;
    40	            }
    41	            if (Boolean.TRUE.equals(existing.getDeleted())) {
    42	                continue; // soft-deleted owners are not counted as possible duplicates
    43	            }
    44	            if (lastName.equals(existing.getLastName())
    45	                    && postcode.equals(existing.getPostcode())
    46	                    && !sameHousehold(owner, existing)
    47	                    && !equalsTelephone(telephone, existing.getTelephone())) {
    48	                if (matchId == null || existing.getId() < matchId) {
    49	                    matchId = existing.getId();
    50	                }
    51	            }
    52	        }
    53	
    54	        if (matchId != null) {
    55	            owner.setPossibleDuplicate(true);
    56	            owner.setPossibleDuplicateOf(matchId);
    57	        }
    58	    }
    59	
    60	    private static boolean equalsTelephone(String a, String b) {
    61	        return a == null ? b == null : a.equals(b);
    62	    }
    63	
    64	    private static boolean sameHousehold(Owner a, Owner b) {
    65	        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
    66	    }
    67	}
===== DeriveHouseholdId.java =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Out;
     4	import net.officefloor.plugin.variable.Val;
     5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     6	
     7	/**
     8	 * Runs in the create-owner pipeline before {@link EnsureUniqueIdentity} and {@link BuildOwner}.
     9	 * Computes the deterministic {@code householdId} — the first 12 hex characters of SHA-256 over the
    10	 * owner's normalized lastName and postcode (see {@link HouseholdId#compute}) — and publishes it as
    11	 * an {@link Out} so {@link EnsureUniqueIdentity} can key duplicate detection on it and
    12	 * {@link AssignHousehold} can stamp it onto the owner being created.
    13	 *
    14	 * <p>Because the identifier is derived from {@code (lastName, postcode)}, owners with the same
    15	 * lastName and postcode share it automatically — no owner has to opt in. {@code sharesHousehold} no
    16	 * longer forms the link; it only bypasses the household duplicate block in
    17	 * {@link EnsureUniqueIdentity}. An owner with no postcode has no shared household, so {@code null}
    18	 * is published and its identityKey carries an empty household component.
    19	 */
    20	public class DeriveHouseholdId {
    21	
    22	    public void service(@Val OwnerFieldsDto request, Out<HouseholdId> householdIdOut) {
    23	        String householdId = HouseholdId.compute(request.getLastName(), request.getPostcode());
    24	        householdIdOut.set(householdId == null ? null : new HouseholdId(householdId));
    25	    }
    26	}
===== HouseholdId.java =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.nio.charset.StandardCharsets;
     4	import java.security.MessageDigest;
     5	import java.security.NoSuchAlgorithmException;
     6	
     7	/**
     8	 * Pipeline variable carrying the deterministic shared household identifier from
     9	 * {@link DeriveHouseholdId} to {@link EnsureUniqueIdentity} and {@link AssignHousehold}. A dedicated
    10	 * type (rather than a raw {@code String}) keeps the OfficeFloor by-type variable matching
    11	 * unambiguous without a qualifier.
    12	 *
    13	 * <p>The identifier is <em>computed</em>, not allocated: {@link #compute} derives it from the
    14	 * owner's normalized lastName and postcode, so owners with the same lastName and postcode share it
    15	 * automatically without any owner opting in.
    16	 */
    17	public final class HouseholdId {
    18	
    19	    private final String value;
    20	
    21	    public HouseholdId(String value) {
    22	        this.value = value;
    23	    }
    24	
    25	    public String value() {
    26	        return this.value;
    27	    }
    28	
    29	    /**
    30	     * The deterministic household identifier: the first 12 hex characters of SHA-256 over
    31	     * {@code normalizedLastName + '|' + postcode}. Owners with the same lastName and postcode
    32	     * therefore always share it.
    33	     *
    34	     * <p>A household is keyed on {@code (lastName, postcode)}, so without a postcode there is no
    35	     * shared household: an absent or blank postcode yields {@code null} (a household of one).
    36	     */
    37	    public static String compute(String lastName, String postcode) {
    38	        if (postcode == null || postcode.isBlank()) {
    39	            return null;
    40	        }
    41	        String seed = normalizeLastName(lastName) + "|" + postcode.trim();
    42	        return sha256Hex12(seed);
    43	    }
    44	
    45	    /** Trim, collapse internal whitespace runs to a single space and lower-case. */
    46	    private static String normalizeLastName(String value) {
    47	        if (value == null) {
    48	            return "";
    49	        }
    50	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    51	    }
    52	
    53	    /** The first 12 hex characters of SHA-256 over {@code seed}. */
    54	    private static String sha256Hex12(String seed) {
    55	        try {
    56	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
    57	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
    58	            StringBuilder hex = new StringBuilder(12);
    59	            for (int i = 0; hex.length() < 12; i++) {
    60	                hex.append(String.format("%02x", hash[i] & 0xff));
    61	            }
    62	            return hex.substring(0, 12);
    63	        } catch (NoSuchAlgorithmException e) {
    64	            throw new IllegalStateException("SHA-256 not available", e); // every JRE ships SHA-256
    65	        }
    66	    }
    67	}
===== AssignHousehold.java =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.springframework.samples.petclinic.model.Owner;
     5	
     6	/**
     7	 * Runs in the create-owner pipeline after {@link BuildOwner}. Stamps the deterministic household
     8	 * identifier computed by {@link DeriveHouseholdId} onto the owner being created so it is stored and
     9	 * returned. Every owner with a postcode gets one (owners sharing lastName and postcode share the
    10	 * value); an owner with no postcode has no shared household and the identifier is {@code null}.
    11	 */
    12	public class AssignHousehold {
    13	
    14	    public void service(@Val Owner owner, @Val HouseholdId householdId) {
    15	        if (householdId != null && householdId.value() != null) {
    16	            owner.setHouseholdId(householdId.value());
    17	        }
    18	    }
    19	}

