22	 * postcode)}, a second owner in that household is a duplicate <em>unless</em> it declares
23	 * {@code sharesHousehold}, which admits it as a member.</li>
24	 * </ul>
25	 */
26	public class EnsureUniqueIdentity {
27	
28	    public void service(@Val OwnerFieldsDto request, @Val HouseholdId householdId,
29	            OwnerRepository ownerRepository) throws DuplicateIdentityException {
30	        String householdIdValue = (householdId == null) ? null : householdId.value();
31	        String identityKey = identityKey(request, householdIdValue);
32	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (Boolean.TRUE.equals(existing.getDeleted())) {
35	                continue; // soft-deleted owners no longer block a create
36	            }
37	            if (identityKey.equals(existing.getIdentityKey())) {
38	                throw new DuplicateIdentityException(identityKey);
39	            }
40	            // A household of one (no postcode) shares with no one; sharesHousehold admits a member.
41	            if (!sharesHousehold && householdIdValue != null
42	                    && householdIdValue.equals(existing.getHouseholdId())) {
43	                throw new DuplicateIdentityException(householdIdValue);
44	            }
45	        }
46	    }
47	
48	    /** Derive the key for the owner being created, matching {@link Owner#getIdentityKey()} exactly. */
49	    private static String identityKey(OwnerFieldsDto request, String householdId) {
50	        String tel = request.getTelephone() == null ? "" : request.getTelephone();
51	        String email = request.getEmail();
52	        String mail = (email == null || email.isBlank()) ? "" : email;
53	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
54	        return tel + "|" + mail + "|" + household;
55	    }
56	}
