7	/**
8	 * Runs in the create-owner pipeline before {@link EnsureUniqueIdentity} and {@link BuildOwner}.
9	 * Computes the deterministic {@code householdId} — the first 12 hex characters of SHA-256 over the
10	 * owner's normalized lastName and postcode (see {@link HouseholdId#compute}) — and publishes it as
11	 * an {@link Out} so {@link EnsureUniqueIdentity} can key duplicate detection on it and
12	 * {@link AssignHousehold} can stamp it onto the owner being created.
13	 *
14	 * <p>Because the identifier is derived from {@code (lastName, postcode)}, owners with the same
15	 * lastName and postcode share it automatically — no owner has to opt in. {@code sharesHousehold} no
16	 * longer forms the link; it only bypasses the household duplicate block in
17	 * {@link EnsureUniqueIdentity}. An owner with no postcode has no shared household, so {@code null}
18	 * is published and its identityKey carries an empty household component.
19	 */
20	public class DeriveHouseholdId {
21	
22	    public void service(@Val OwnerFieldsDto request, Out<HouseholdId> householdIdOut) {
23	        String householdId = HouseholdId.compute(request.getLastName(), request.getPostcode());
24	        householdIdOut.set(householdId == null ? null : new HouseholdId(householdId));
25	    }
