2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Soft-match step in the create-owner pipeline. Runs after {@link BuildOwner} (so the owner carries
9	 * its normalized telephone, lastName and postcode) and before {@link SaveOwner}. It is reached only
10	 * for owners that already passed {@link EnsureUniqueIdentity}, i.e. that are NOT hard duplicates.
11	 *
12	 * <p>An owner is a <em>possible</em> duplicate when an existing owner shares its {@code lastName}
13	 * and {@code postcode} but has a different {@code telephone}. When such an owner exists the new
14	 * owner is still created, but flagged with {@code possibleDuplicate = true} and
15	 * {@code possibleDuplicateOf} set to the matching owner's id (the lowest id when several match).
16	 * Otherwise {@code possibleDuplicate} is set to {@code false} and no match id is recorded.
17	 *
18	 * <p>An existing owner in the <em>same household</em> (same computed {@code householdId}) is never a
19	 * soft match: a second owner sharing lastName and postcode is either rejected as a household
20	 * duplicate ({@link EnsureUniqueIdentity}) or admitted as a declared member via
21	 * {@code sharesHousehold}, and a declared member is not a suspected duplicate.
22	 */
23	public class DetectPossibleDuplicate {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        owner.setPossibleDuplicate(false);
27	        owner.setPossibleDuplicateOf(null);
28	
29	        String lastName = owner.getLastName();
30	        String postcode = owner.getPostcode();
31	        String telephone = owner.getTelephone();
32	        if (lastName == null || postcode == null || postcode.isBlank()) {
33	            return; // a shared lastName+postcode is required to be a possible duplicate
34	        }
35	
36	        Integer matchId = null;
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (existing.getId() == null) {
39	                continue;
40	            }
41	            if (Boolean.TRUE.equals(existing.getDeleted())) {
42	                continue; // soft-deleted owners are not counted as possible duplicates
43	            }
44	            if (lastName.equals(existing.getLastName())
45	                    && postcode.equals(existing.getPostcode())
46	                    && !sameHousehold(owner, existing)
47	                    && !equalsTelephone(telephone, existing.getTelephone())) {
48	                if (matchId == null || existing.getId() < matchId) {
49	                    matchId = existing.getId();
50	                }
51	            }
52	        }
53	
54	        if (matchId != null) {
55	            owner.setPossibleDuplicate(true);
56	            owner.setPossibleDuplicateOf(matchId);
57	        }
58	    }
59	
60	    private static boolean equalsTelephone(String a, String b) {
61	        return a == null ? b == null : a.equals(b);
62	    }
63	
64	    private static boolean sameHousehold(Owner a, Owner b) {
65	        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
66	    }
67	}
