1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs in the create-owner pipeline after {@link AssignHousehold} (which stamps the shared
9	 * {@code householdId}) and before {@link SaveOwner}. Records how many owners share this owner's
10	 * household as of this create.
11	 *
12	 * <p>The owner being created is not yet persisted, so its own membership is counted with the seed
13	 * {@code 1} and every already-stored owner carrying the same non-null {@code householdId} adds one.
14	 * An owner with no household ({@code householdId == null}) is a household of one and never groups with
15	 * other household-less owners.
16	 */
17	public class AssignHouseholdSize {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = owner.getHouseholdId();
21	        if (householdId == null) {
22	            owner.setHouseholdSize(1); // unique household — just this owner
23	            return;
24	        }
25	        int members = 1; // this owner, not yet saved
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (householdId.equals(existing.getHouseholdId())) {
28	                members++;
29	            }
30	        }
31	        owner.setHouseholdSize(members);
32	    }
33	}
