56	    /**
57	     * Enforces the national-number length for country codes that fix it: {@code '61'} requires 9
58	     * national digits, {@code '1'} requires 10. Country codes without a rule pass through.
59	     */
60	    private static void requireNationalLength(String digits, String raw)
61	            throws InvalidTelephoneException {
62	        int required;
63	        int nationalLength;
64	        if (digits.startsWith("61")) {
65	            required = 9;
66	            nationalLength = digits.length() - 2;
67	        } else if (digits.startsWith("1")) {
68	            required = 10;
69	            nationalLength = digits.length() - 1;
70	        } else {
71	            return; // no length rule for this country code
72	        }
