1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
8	
9	/**
10	 * Shared email handling for the owner pipeline. Not an OfficeFloor function class (it is never
11	 * referenced from a step), so it may expose helper methods.
12	 */
13	final class OwnerEmails {
14	
15	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
16	
17	    /** Disposable / throwaway email domains that a create-owner request may not use. */
18	    private static final Set<String> DISPOSABLE_DOMAINS =
19	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    private OwnerEmails() {
22	    }
23	
24	    /**
25	     * Rejects an email whose domain is on the disposable-domain blocklist. An absent value (null or
26	     * blank) passes through untouched; a present value is expected to already be
27	     * {@link #normalize(String) normalized} (lower-cased), so the domain comparison is exact.
28	     */
29	    static void rejectDisposableDomain(String email) throws DisposableEmailDomainException {
30	        if (email == null || email.isBlank()) {
31	            return;
32	        }
33	        int at = email.lastIndexOf('@');
34	        if (at < 0) {
35	            return;
36	        }
37	        String domain = email.substring(at + 1);
38	        if (DISPOSABLE_DOMAINS.contains(domain)) {
39	            throw new DisposableEmailDomainException(email);
40	        }
41	    }
42	
43	    /**
44	     * Returns the email lower-cased, or the original value unchanged when absent (null or blank).
45	     * Throws when a present value is not a syntactically valid address.
46	     */
47	    static String normalize(String email) throws InvalidEmailException {
48	        if (email == null || email.isBlank()) {
49	            return email;
50	        }
51	        if (!EMAIL.matcher(email).matches()) {
52	            throw new InvalidEmailException(email);
53	        }
54	        return email.toLowerCase();
55	    }
56	}
