1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
8	
9	/**
10	 * Runs in the create-owner pipeline after {@link BuildOwner}. Validates the owner's postcode ONLY
11	 * when one is present: an absent (or blank) postcode is optional and accepted, keeping the request
12	 * contract backward-compatible. When present it must be exactly four digits and, when the owner's
13	 * city maps to a known region, fall within that region's inclusive postcode range (NSW 2000-2099,
14	 * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. Anything
15	 * else is rejected with a 400.
16	 *
17	 * <p>The region is resolved from the owner's <em>city</em> (not {@link Owner#getLocality()}, which
18	 * prefers the postcode itself): the city is the authority the postcode is checked against, so a
19	 * postcode that happens to fall in another region's range is still rejected for a city that maps to
20	 * a known region.
21	 */
22	public class ValidateOwnerPostcode {
23	
24	    /** Region -> inclusive 4-digit postcode range {low, high}. */
25	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
26	            "NSW", new int[] {2000, 2099},
27	            "VIC", new int[] {3000, 3099},
28	            "QLD", new int[] {4000, 4099});
29	
30	    /** City -> canonical region; anything not listed has no known region. */
31	    private static final Map<String, String> CITY_REGION =
32	            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
33	
34	    public void service(@Val Owner owner) throws InvalidPostcodeException {
35	        String postcode = owner.getPostcode();
36	        if (postcode == null || postcode.isBlank()) {
37	            return; // optional when absent
38	        }
39	        if (!postcode.matches("[0-9]{4}")) {
40	            throw new InvalidPostcodeException(postcode);
41	        }
42	        String region = CITY_REGION.get(owner.getCity());
43	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
44	        if (range != null) {
45	            int value = Integer.parseInt(postcode);
46	            if (value < range[0] || value > range[1]) {
47	                throw new InvalidPostcodeException(postcode);
48	            }
49	        }
50	    }
51	}
