1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.server.http.HttpHeader;
4	import net.officefloor.server.http.ServerHttpConnection;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.escalation.IdempotentReplayException;
8	
9	/**
10	 * Runs first in the create-owner pipeline. If the request carries an {@code Idempotency-Key} header
11	 * that {@link IdempotencyStore} has already seen, and the owner it created still exists, throws
12	 * {@link IdempotentReplayException} carrying that owner so the pipeline short-circuits to a 200 replay
13	 * before any duplicate can be created (which would otherwise 409). Otherwise it does nothing and the
14	 * normal validate/build/save pipeline proceeds; {@link RecordIdempotentCreate} records the key once
15	 * the owner has been saved.
16	 */
17	public class CheckIdempotentCreate {
18	
19	    public static final String HEADER = "Idempotency-Key";
20	
21	    public void service(ServerHttpConnection connection, IdempotencyStore store,
22	            OwnerRepository ownerRepository) throws IdempotentReplayException {
23	        String key = idempotencyKey(connection);
24	        if (key == null) {
25	            return;
26	        }
27	        Integer ownerId = store.find(key);
28	        if (ownerId == null) {
29	            return;
30	        }
31	        Owner owner = ownerRepository.findById(ownerId);
32	        if (owner != null && !Boolean.TRUE.equals(owner.getDeleted())) {
33	            throw new IdempotentReplayException(owner);
34	        }
35	    }
36	
37	    /** The trimmed {@code Idempotency-Key} header value, or {@code null} when absent or blank. */
38	    static String idempotencyKey(ServerHttpConnection connection) {
39	        HttpHeader header = connection.getRequest().getHeaders().getHeader(HEADER);
40	        if (header == null) {
41	            return null;
42	        }
43	        String value = header.getValue();
44	        return (value == null || value.isBlank()) ? null : value.trim();
45	    }
46	}
