4	import org.junit.jupiter.api.Test;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
6	import tools.jackson.databind.node.ObjectNode;
7	
8	/** soft-match: the soft match now triggers on soundex(lastName) + postcode with
9	 * a differing identityKey. Two owners with the same lastName (same soundex) and postcode, different
10	 * telephone, flag the second as a possible duplicate of the first. */
11	@Tag("cp35")
12	class Cp35Tests extends AcceptanceBase {
13	
14		@Test
15		void coreSoftMatchOnSoundexAndPostcode() throws Exception {
16			String lastName = uniqueLastName();
17			ObjectNode a = withPostcode(ownerNode());
18			a.put("lastName", lastName);
19			int ida = createOwnerOk(a);
20			ObjectNode b = withPostcode(ownerNode());
21			b.put("lastName", lastName);
22			int idb = createOwnerOk(b);
23			getOwner(idb).andExpect(jsonPath("$.possibleDuplicate").value(true))
24					.andExpect(jsonPath("$.possibleDuplicateOf").value(ida));
25		}
26	}
