10	/** identity-key-v2: identityKey = SHA-256 hex over (normalizedTelephone | lowerEmail |
11	 * soundex(lastName)); duplicate detection (409) uses it. The exact key depends on soundex, so the
12	 * deterministic oracle is the collision (identical identity -> 409) plus the exact 64-hex shape. */
13	@Tag("cp52")
14	class Cp52Tests extends AcceptanceBase {
15	
16		@Test
17		void coreIdentityKeyIsSha256Hex() throws Exception {
18			JsonNode r = fetchOwner(createOwnerOk(structuredOwner()));
19			String key = r.get("identityKey").asText();
20			assertTrue(key.matches("[0-9a-f]{64}"), key);
21		}
22	
23		@Test
24		void coreRejectsDuplicateIdentity() throws Exception {
25			ObjectNode a = structuredOwner();
26			a.put("email", uniqueEmail());
27			createOwnerOk(a);
28			ObjectNode b = a.deepCopy(); // identical telephone / email / lastName -> same v2 key
29			createOwner(b).andExpect(status().isConflict());
30		}
