11	/**
12	 * Runs first in the create-owner pipeline. Rejects a request that is missing or blank in any of
13	 * firstName, lastName, address, city or telephone with a 400 naming each offending field, before
14	 * {@link BuildOwner} runs. Publishes the validated body for later steps as they must not bind the
15	 * request body a second time.
16	 *
17	 * <p>An address may be supplied structured (a non-blank {@code addressLine1} plus optional
18	 * {@code addressLine2}) or flat ({@code address}); an owner is valid when it supplies either.
19	 * {@link OwnerAddresses#applyTo} normalizes whichever fields are present in place and composes the
20	 * flat {@code address} (structured preferred) before it is checked and published, so an address
21	 * blank in both forms is rejected here and every later step (build, household comparison,
22	 * store/return) works with the single normalized composed form.
23	 */
24	public class ValidateOwnerFields {
25	
26	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
27	            throws MissingOwnerFieldsException {
28	        OwnerAddresses.applyTo(request);
29	
30	        List<String> missing = new ArrayList<>();
31	        require("firstName", request.getFirstName(), missing);
32	        require("lastName", request.getLastName(), missing);
33	        require("address", request.getAddress(), missing);
34	        require("city", request.getCity(), missing);
35	        require("telephone", request.getTelephone(), missing);
36	        if (!missing.isEmpty()) {
37	            throw new MissingOwnerFieldsException(missing);
38	        }
39	        validated.set(request);
40	    }
41	
42	    private static void require(String name, String value, List<String> missing) {
43	        if (value == null || value.isBlank()) {
44	            missing.add(name);
45	        }
46	    }
47	}
